#!/usr/bin/env bash
# Usage: checks.sh <label> <worktree> [gate]. With "gate": fmt, clippy, tests and the seed sweep only (the merge gate); without, also ai_games. The Director's integration checks; writes <label>_checks.log and <label>_ai_games.txt.
S=/tmp/claude-1000/-home-iv-dev-space-crystals/0fe17aed-7223-49e6-819d-e4ea988641e6/scratchpad
X=${1:?label}; WT=${2:?worktree}; L=$S/${X}_checks.log; T=$S/${X}_ai_games.txt
( cd "$WT" && { echo "== head $(git rev-parse --short HEAD), status: $(git status --porcelain | wc -l) changes"; echo "== fmt"; cargo fmt --all --check 2>&1 | tail -5; echo "fmt rc=${PIPESTATUS[0]}"; echo "== clippy"; cargo clippy --workspace --all-targets -q -- -D warnings 2>&1 | tail -15; echo "clippy rc=${PIPESTATUS[0]}"; echo "== test"; cargo test --workspace --no-fail-fast 2>&1 | grep -E '^test result|FAILED|panicked|^error|Running' | awk '/Running/{n++; next} /^test result/{p+=$4; f+=$6; i+=$8; next} {print} END{print "programs",n,"passed",p,"failed",f,"ignored",i}'; echo "test rc=${PIPESTATUS[0]}"; echo "== seed sweep"; cargo test --workspace -- --ignored seed_sweep 2>&1 | grep -E 'seed_sweep|FAILED|panicked'; if [ "${3:-}" != gate ]; then echo "== ai_games (ignored)"; cargo test --release -p sc_ai --test ai games::ai_games -- --ignored --nocapture 2>&1 | grep -vE '^\s*$|Compiling|Running|Finished|running [0-9]+ test|filtered out' > "$T"; grep -E "gdo,gdo|test games|Ai::think|panicked|FAILED|error" "$T" | tail -20; echo "rows: $(grep -c -- '--' "$T")"; fi; uptime; } > "$L" 2>&1 )
